const request = $json ?? {};
const headers = request.headers && typeof request.headers === 'object' ? request.headers : {};
const getHeader = (name) => { const lower = String(name).toLowerCase(); const key = Object.keys(headers).find((item) => String(item).toLowerCase() === lower); return key ? headers[key] : undefined; };
const expectedToken = String($env.N8N_WORKFLOWS_TOKEN || '').trim();
const providedToken = String(getHeader('authorization') || getHeader('x-aiops-workflows-token') || '').trim().replace(/^bearer\s+/i, '').trim();
if (!expectedToken) return [{ json: { ok: false, status_code: 500, error: 'N8N_WORKFLOWS_TOKEN is not set' } }];
if (providedToken !== expectedToken) return [{ json: { ok: false, status_code: 401, error: 'invalid workflows token' } }];
const rawBase = String($env.N8N_WEBHOOK_BASE_URL || ($env.N8N_PUBLIC_API_BASE_URL ? `${String($env.N8N_PUBLIC_API_BASE_URL).replace(/\/+$/, '')}/webhook` : '')).replace(/\/+$/, '');
if (!rawBase) return [{ json: { ok: false, status_code: 500, error: 'webhook base URL is not configured' } }];
const payload = request.body && typeof request.body === 'object' ? request.body : {};
const baseVersion = String(payload.base_version ?? payload.baseVersion ?? '3.0.3').trim();
const targetVersion = String(payload.target_version ?? payload.targetVersion ?? '3.0.4').trim();
const description = ['## 種別', '種別：変更', '', '## 対象サービス', 'Sulu', '', '## 現行バージョン', baseVersion, '', '## 修正対象バージョン', targetVersion, '', '## 変更内容', 'Suluを修正対象バージョンへ更新する。'].join('\n');
try {
  const response = await this.helpers.httpRequest({ method: 'POST', url: `${rawBase}/sulu/rfc-source-analysis`, json: true, timeout: 120000, headers: { Authorization: `Bearer ${expectedToken}` }, body: { realm: String(payload.realm ?? $env.N8N_REALM ?? $env.N8N_ENV_REALM ?? 'aiops'), rfc: { id: 'RFC-OQ-SULU-VERSION', iid: 0, title: `RFC: Sulu ${targetVersion}修正依頼`, description, labels: ['ITSM/変更管理', 'RFC'], state: 'opened' }, correlation_id: 'oq-sulu-rfc-source-analysis-selftest' } });
  const passed = response?.ok === true && response?.workflow_id === 'wf.sulu_rfc_source_analysis' && response?.status === 'analyzed_from_rfc' && response?.rfc?.extracted_target_version === targetVersion && response?.versions?.base_version === baseVersion && response?.versions?.target_version === targetVersion && Number(response?.comparison?.changed_files ?? 0) > 0 && Array.isArray(response?.findings) && response.findings.length > 0;
  return [{ json: { ok: passed, status_code: passed ? 200 : 500, target_response: response, error: passed ? null : 'RFC source analysis assertions failed' } }];
} catch (error) { return [{ json: { ok: false, status_code: 500, error: error?.message ? String(error.message) : String(error) } }]; }

const result = $json ?? {};
const publish = result.target_response?.image_publish ?? {};
const passed = result.ok === true && publish.status === 'validated' && publish.dryRun === true && publish.applied === false && publish.latestTagPreserved === true;
return [{ json: { ...result, ok: passed, status_code: passed ? 200 : 500, error: passed ? null : 'RFC image publish dry-run assertions failed' } }];
